#!/usr/bin/env python3"""Insert functions into prompts.py using byte-level manipulation."""import sysimport tracebackfrom pathlib import Pathtry:    target = Path("bin/agent/prompts.py")    raw = target.read_bytes()        # Write debug info to file    debug = []    debug.append(f"File size: {len(raw)}")    debug.append(f"Has CRLF: {b'\r\n' in raw}")        # Find anchor: "    return prompt\r\n"    anchor1 = b"    return prompt\r\n"    idx1 = raw.find(anchor1)    debug.append(f"Anchor1 'return prompt' at: {idx1}")        if idx1 >= 0:        # Show context        debug.append(f"Context after anchor: {repr(raw[idx1:idx1+100])}")        # Find anchor2: "def read_prompts_config("    anchor2 = b"def read_prompts_config("    idx2 = raw.find(anchor2)    debug.append(f"Anchor2 'read_prompts_config' at: {idx2}")        # Find CLI anchor    cli_anchor = b'    if "--reset-system" in args:'    idx3 = raw.find(cli_anchor)    debug.append(f"CLI anchor at: {idx3}")        Path(".agentic/debug_info.txt").write_text("\n".join(debug), encoding="utf-8")        if idx1 < 0:        sys.exit(1)        # Build the serialize block    serialize_block = b"\r\ndef _serialize_element(elem: ET.Element, indent: str = \"\") -> str:\r\n    \"\"\"Serialize an Element to XML string with CDATA for value elements.\"\"\"\r\n    parts: list[str] = []\r\n    tag = elem.tag\r\n    attrs = \"\"\r\n    for k, v in elem.attrib.items():\r\n        attrs += f' {k}=\"{v}\"'\r\n    children = list(elem)\r\n    has_children = len(children) > 0\r\n    if tag == \"value\" and elem.text:\r\n        parts.append(f\"{indent}<{tag}{attrs}><![CDATA[{elem.text}]]></{tag}>\")\r\n        return \"\".join(parts)\r\n    if not has_children and (elem.text is None or not elem.text.strip()):\r\n        parts.append(f\"{indent}<{tag}{attrs} />\")\r\n    elif not has_children:\r\n        parts.append(f\"{indent}<{tag}{attrs}>{elem.text or ''}</{tag}>\")\r\n    else:\r\n        parts.append(f\"{indent}<{tag}{attrs}>\")\r\n        for child in children:\r\n            parts.append(\"\\n\")\r\n            parts.append(_serialize_element(child, indent + \"  \"))\r\n        parts.append(f\"\\n{indent}</{tag}>\")\r\n    return \"\".join(parts)\r\n\r\ndef _write_prompts_xml(tree: ET.ElementTree, target: Path) -> None:\r\n    \"\"\"Write the prompts XML tree to target using CDATA for value elements.\"\"\"\r\n    root = tree.getroot()\r\n    xml_str = '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\\n'\r\n    xml_str += _serialize_element(root)\r\n    xml_str += \"\\n\"\r\n    target.write_text(xml_str, encoding=\"utf-8\")\r\n"        # Insert after anchor1    insert_pos = idx1 + len(anchor1)    raw = raw[:insert_pos] + serialize_block + raw[insert_pos:]        # Re-find anchor2 (positions shifted)    idx2 = raw.find(anchor2)    if idx2 < 0:        Path(".agentic/debug_info.txt").write_text("ERROR: anchor2 not found after insert1", encoding="utf-8")        sys.exit(1)        # Build update_base_prompts_from_xml    update_block = b"def update_base_prompts_from_xml(path: str | Path | None = None) -> Path:\r\n    \"\"\"Read XML system values and write them back as hardcoded defaults here.\"\"\"\r\n    target = Path(path).expanduser().resolve() if path else prompts_config_path()\r\n    if not target.exists():\r\n        raise FileNotFoundError(f\"prompts_config.xml not found at {target}\")\r\n    tree = _read_tree(target)\r\n    root = tree.getroot()\r\n    system, _project = _ensure_sections(root)\r\n    xml_prompts = _read_prompt_section(system)\r\n    if not xml_prompts:\r\n        return target\r\n    this_file = Path(__file__).resolve()\r\n    src = this_file.read_text(encoding=\"utf-8\")\r\n    lines: list[str] = [\"DEFAULT_SYSTEM_PROMPTS: Dict[str, str] = {\"]\r\n    seen: set[str] = set()\r\n    for key in DEFAULT_SYSTEM_PROMPTS:\r\n        seen.add(key)\r\n        value = xml_prompts.get(key, DEFAULT_SYSTEM_PROMPTS[key])\r\n        lines.append(f\"    {key!r}: {value!r},\")\r\n    for key, value in xml_prompts.items():\r\n        if key in seen:\r\n            continue\r\n        lines.append(f\"    {key!r}: {value!r},\")\r\n    lines.append(\"}\")\r\n    new_block = \"\\n\".join(lines)\r\n    import re as _re\r\n    pattern = _re.compile(\r\n        r\"DEFAULT_SYSTEM_PROMPTS:\\s*Dict\\[str,\\s*str\\]\\s*=\\s*\\{.*?\\n\\}\",\r\n        _re.DOTALL,\r\n    )\r\n    if not pattern.search(src):\r\n        raise RuntimeError(\"Could not locate DEFAULT_SYSTEM_PROMPTS dict\")\r\n    updated = pattern.sub(new_block, src, count=1)\r\n    this_file.write_text(updated, encoding=\"utf-8\")\r\n    return target\r\n\r\n"        raw = raw[:idx2] + update_block + raw[idx2:]        # Add --update-base CLI flag    cli_old = b'    if "--reset-system" in args:\r\n        print(reset_system_prompts_to_defaults())\r\n        return 0'    cli_new = b'    if "--update-base" in args:\r\n        print(update_base_prompts_from_xml())\r\n        return 0\r\n    if "--reset-system" in args:\r\n        print(reset_system_prompts_to_defaults())\r\n        return 0'        if cli_old in raw:        raw = raw.replace(cli_old, cli_new, 1)        target.write_bytes(raw)    Path(".agentic/debug_info.txt").write_text(f"SUCCESS: file written, new size {len(raw)}", encoding="utf-8")    except Exception:    Path(".agentic/debug_info.txt").write_text(traceback.format_exc(), encoding="utf-8")